@CrossOrigin
@RestController
@RequestMapping("/WarrantyQuery")
public class WarrantyQueryRestController extends BaseSpringRestController {
	
	public WarrantyQueryRestController( WarrantyService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Warranty using a UUID
     * @param		UUID warrantyId
     * @return		Warranty
     */    
    @GetMapping("/load")
    public Warranty load( @RequestParam(required=true) UUID warrantyId ) {
    	Warranty entity = null;

    	try {  
    		entity = service.getWarranty( new WarrantyFetchOneSummary( warrantyId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Warranty using Id " + warrantyId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Warranty business objects
     * @return		Set<Warranty>
     */
    @GetMapping("/")
    public List<Warranty> loadAll() {                
    	List<Warranty> warrantyList = null;
        
    	try {
            // load the Warranty
            warrantyList = service.getAllWarranty();
            
            if ( warrantyList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Warrantys" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Warrantys ", exc );
        	return null;
        }

        return warrantyList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Warranty warranty = null;
    protected WarrantyService service = null;
    private static final Logger LOGGER = Logger.getLogger(WarrantyQueryRestController.class.getName());
    
}
